    Bug 1718998 - Rename misleading var in nsImapMoveCopyTxn. r=aleca

    Not strictly a comment change, but purely cosmetic. Doesn't affect generated code.

    Differential Revision: https://phabricator.services.mozilla.com/D218278

diff --git a/mailnews/imap/src/nsImapUndoTxn.cpp b/mailnews/imap/src/nsImapUndoTxn.cpp
index 68183498645..2a0d5d82cd0 100644
--- a/mailnews/imap/src/nsImapUndoTxn.cpp
+++ b/mailnews/imap/src/nsImapUndoTxn.cpp
@@ -16,7 +16,7 @@
 #include "nsServiceManagerUtils.h"

 nsImapMoveCopyMsgTxn::nsImapMoveCopyMsgTxn()
-    : m_idsAreUids(false), m_isMove(false), m_srcIsPop3(false) {}
+    : m_idsAreUids(false), m_isMove(false), m_srcIsLocal(false) {}

 nsresult nsImapMoveCopyMsgTxn::Init(nsIMsgFolder* srcFolder,
                                     nsTArray<nsMsgKey>* srcKeyArray,
@@ -47,11 +47,12 @@ nsresult nsImapMoveCopyMsgTxn::Init(nsIMsgFolder* srcFolder,
     if (NS_SUCCEEDED(rv)) {
       // ** jt -- only do this for mailbox protocol
       if (protocolType.LowerCaseEqualsLiteral("mailbox")) {
-        m_srcIsPop3 = true;
+        m_srcIsLocal = true;
         uint32_t msgSize;
         rv = srcHdr->GetMessageSize(&msgSize);
         if (NS_SUCCEEDED(rv)) m_srcSizeArray.AppendElement(msgSize);
         if (isMove) {
+          // Copy the src msgHdrs, but don't add to the db.
           rv = srcDB->CopyHdrFromExistingHdr(nsMsgKey_None, srcHdr, false,
                                              getter_AddRefs(copySrcHdr));
           nsMsgKey pseudoKey = nsMsgKey_None;
@@ -83,7 +84,7 @@ nsImapMoveCopyMsgTxn::UndoTransaction(void) {
   bool finishInOnStopRunningUrl = false;

   if (m_isMove || !m_dstFolder) {
-    if (m_srcIsPop3) {
+    if (m_srcIsLocal) {
       rv = UndoMailboxDelete();
       NS_ENSURE_SUCCESS(rv, rv);
     } else {
@@ -160,7 +161,7 @@ nsImapMoveCopyMsgTxn::RedoTransaction(void) {
   NS_ENSURE_SUCCESS(rv, rv);

   if (m_isMove || !m_dstFolder) {
-    if (m_srcIsPop3) {
+    if (m_srcIsLocal) {
       rv = RedoMailboxDelete();
       if (NS_FAILED(rv)) return rv;
     } else if (!m_srcMsgIdString.IsEmpty()) {
@@ -251,7 +252,7 @@ nsresult nsImapMoveCopyMsgTxn::AddDstKey(nsMsgKey aKey) {
 nsresult nsImapMoveCopyMsgTxn::UndoMailboxDelete() {
   nsresult rv = NS_ERROR_FAILURE;
   // ** jt -- only do this for mailbox protocol
-  if (m_srcIsPop3) {
+  if (m_srcIsLocal) {
     nsCOMPtr<nsIMsgFolder> srcFolder = do_QueryReferent(m_srcFolder, &rv);
     if (NS_FAILED(rv) || !srcFolder) return rv;

@@ -290,7 +291,7 @@ nsresult nsImapMoveCopyMsgTxn::UndoMailboxDelete() {

 nsresult nsImapMoveCopyMsgTxn::RedoMailboxDelete() {
   nsresult rv = NS_ERROR_FAILURE;
-  if (m_srcIsPop3) {
+  if (m_srcIsLocal) {
     nsCOMPtr<nsIMsgDatabase> srcDB;
     nsCOMPtr<nsIMsgFolder> srcFolder = do_QueryReferent(m_srcFolder, &rv);
     if (NS_FAILED(rv) || !srcFolder) return rv;
diff --git a/mailnews/imap/src/nsImapUndoTxn.h b/mailnews/imap/src/nsImapUndoTxn.h
index edb432bb014..a97d9faaf95 100644
--- a/mailnews/imap/src/nsImapUndoTxn.h
+++ b/mailnews/imap/src/nsImapUndoTxn.h
@@ -50,9 +50,10 @@ class nsImapMoveCopyMsgTxn : public nsMsgTxn, nsIUrlListener {
   nsCString m_srcMsgIdString;
   nsWeakPtr m_dstFolder;
   nsCString m_dstMsgIdString;
+  // Set if message IDs are IMAP UIDs, clear if IMAP sequence numbers.
   bool m_idsAreUids;
   bool m_isMove;
-  bool m_srcIsPop3;
+  bool m_srcIsLocal;
   nsTArray<uint32_t> m_srcSizeArray;
   // this is used when we chain urls for imap undo, since "this" needs
   // to be the listener, but the folder may need to also be notified.
